changeSet.sql:
          INSERT INTO data.symbol(code,id_coin) 
          select ds.symbolCode,c.id
          from(
	          SELECT symbolCode, coinCode
	          FROM unnest(ARRAY['BTCUSDT','DOGEUSDT','SOLUSDT','GRAMUSDT','MNTUSDT','TRXUSDT','ADAUSDT','ETHUSDT','XRPUSDT','DOTUSDT'],  
	                      ARRAY['BTC','DOGE','SOL','GRAM','MNT','TRX','ADA','ETH','XRP','DOT']
	                      ) AS t(symbolCode, coinCode)
          ) ds
          join data.coin c on c.code = ds.coinCode;
